import os
import re
import subprocess
from pyparsing import Forward, Suppress, Optional, Word, alphanums, Regex, SkipTo, Group, OneOrMore, delimitedList


class AsnMsg():
    def __init__(self, data):
        self.data = data

        expr = Forward()
        LP = Suppress('{')
        RP = Suppress('}')
        DD = Optional(Suppress(':'))
        DE = Suppress('::=')
        key = Word(alphanums + '-')
        value = (Word(alphanums + '-') | Regex(r"(?:'|\").*?(?:'|\")[HB]?", flags=re.MULTILINE | re.DOTALL))
        adict = Forward()
        adict << Group(key + DD + (Group(adict) | expr | value)).setParseAction(lambda t: ["!DICT", t])
        bdict = Group(key + DD + (Group(adict) | expr | value)) | expr
        delim_list = (LP + delimitedList(value | expr) + RP).setParseAction(lambda t: ["!LIST", t])
        delim_dict = (LP + delimitedList(bdict) + RP).setParseAction(lambda t: ["!DICT", t])
        empty_dict = (LP + RP).setParseAction(lambda t: ["!DICT", []])
        expr << Group(delim_list | delim_dict | empty_dict | adict)
        header = Regex(r"value .+ ::=")
        full_expr = Suppress(SkipTo(header)) + Suppress("value") + Group(key + DE + expr)
        full_expr = full_expr.setParseAction(lambda t: ["!DICT", t])
        full_expr = OneOrMore(Group(full_expr)).setParseAction(lambda t: ["!LIST", t])

        self.parsed_data = full_expr.parseString(self.data).asList()

    def _convert_data(self, parsed_data):
        if parsed_data == 'NULL':
            return None
        elif parsed_data in ['inf', 'infinity']:
            return 'inf'
        else:
            return self._convert_valid_data(parsed_data)

    def _convert_valid_data(self, data):
        if data.isdigit():
            return int(data)
        try:
            return float(data)
        except ValueError:
            pass
        hex_expression = re.match(r"'(\w+)'H", data)
        if hex_expression is not None:
            return '0x' + hex_expression.group(1)
        bin_expression = re.match(r"'([ 01]+)'B", data)
        if bin_expression is not None:
            return '0b' + re.sub(' ', '', bin_expression.group(1))
        return data

    def _create_struct(self, parsed_data):
        if parsed_data[0] == '!DICT':
            out = {}
            for k in parsed_data[1]:
                out[k[0]] = self._create_struct(k[1])
            return out
        if parsed_data[0] == '!LIST':
            out = []
            for k in parsed_data[1]:
                out.append(self._create_struct(k))
            return out

        return self._convert_data(parsed_data)

    def get(self):
        ret = self._create_struct(self.parsed_data)
        if isinstance(ret, list) and len(ret) == 1:
            return ret[0]
        return ret


class ASNCoder:
    PROT2PDU = {
        "S1AP": "S1AP-PDU", "X2AP": "X2AP-PDU", "XnAP": "XnAP-PDU", "F1AP": "F1AP-PDU", "NGAP": "NGAP-PDU",
        "RRC5G": "CellGroupConfig",
    }

    UES_PATHS = ["/opt/emssim/util/uesim-dump", "/opt/cus/bin/uesim-dump"]

    PATT_META_CMD = re.compile(r"@dump ")
    PATT_WHITE_END = re.compile(r"\S\s$")
    PATT_OPEN_CURLY = re.compile(r"^\s*{\s*$")
    PATT_WHITE_START = re.compile(r"^  ")
    PATT_BINARY_WITH_WHITE = re.compile(r"('[01]+\s+.*?'B)")

    def __init__(self, protocol):
        self.protocol = protocol
        self.uesim_dump_path = None
        self.set_uesim_dump_path()

    def set_uesim_dump_path(self):
        for fpath in self.UES_PATHS:
            if self.is_exec(fpath):
                self.uesim_dump_path = fpath
                return

    def is_exec(self, fpath):
        if fpath and os.path.isfile(fpath) and os.access(fpath, os.X_OK):
            return True
        return False

    def is_ready(self):
        if self.uesim_dump_path:
            return True
        return False

    def decode_asn(self, msg, pdu_type=None, harmonize=False):
        return self.hex2asn(msg, pdu_type, harmonize)

    def decode_rrc5g_asn_dl_dcch(self, msg):
        return self.decode_asn(msg, pdu_type="dl-dcch")

    def decode_rrc5g_asn_ul_dcch(self, msg):
        return self.decode_asn(msg, pdu_type="ul-dcch")

    def encode_rrc5g_asn(self, msg: str):
        if msg.startswith('0x'):
            return msg
        return self.encode_asn(msg, pdu_type="RRC5G", prefix=True)

    def encode_asn(self, msg, pdu_type=None, prefix=False):
        add_prefix = True if not prefix else False
        return self.asn2hex(msg, pdu_type, add_prefix)

    def add_encoder_prefix(self, msg, pdu_type):
        return "value %s ::= " % str(pdu_type) + msg

    def asn2hex(self, data_str, pdu_type, add_prefix):
        if add_prefix:
            data_str = self.add_encoder_prefix(data_str, self.PROT2PDU[self.protocol])
        if pdu_type:
            lines = self.run_pipe_cmd([self.uesim_dump_path, "-a", "-A", pdu_type, "-"], data_str)
        else:
            lines = self.run_pipe_cmd([self.uesim_dump_path, "-a", "-"], data_str)
        for line in lines:
            srch = re.search(r"ASN1-VALUE value\s+\S+\s(\S+)", str(line))
            if srch:
                return srch.group(1)
        return ""

    def asn2py(self, msg_str):
        return AsnMsg(msg_str).get()

    def hex2asn(self, data_hex, pdu_type, harmonize):
        if not pdu_type:
            pdu_type = self.PROT2PDU[self.protocol]

        meta_cmd = "@dump %s %s %s" % (
            self.protocol.lower(),
            pdu_type,
            data_hex,
        )

        lines = self.run_pipe_cmd([self.uesim_dump_path], meta_cmd)
        if self.PATT_META_CMD.search(lines[0]):
            lines.pop(0)
        if harmonize:
            lines_out = self.hex2asn_harmonize(lines)
        else:
            lines_out = lines
        return "\n".join(lines_out)

    def hex2asn_harmonize(self, lines):
        lines_out = []
        i = 0
        imax = len(lines)
        while i < imax:
            line = lines[i]
            if self.PATT_WHITE_START.match(line):
                line = line[2:]
            bww = self.PATT_BINARY_WITH_WHITE.search(line)
            if bww:
                bin_str = bww.group(1)
                bin_str_new = re.sub(r"\s+", r"", bin_str)
                line = self.PATT_BINARY_WITH_WHITE.sub(bin_str_new, line)

            if (
                (i < imax - 1)
                and self.PATT_WHITE_END.search(line)
                and self.PATT_OPEN_CURLY.search(lines[i + 1])
            ):
                line += "{"
                i += 1
            lines_out.append(line)
            i += 1
        return lines_out

    def run_pipe_cmd(self, cmd, pipe):
        p = subprocess.Popen(
            cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, stdin=subprocess.PIPE
        )
        out, err = p.communicate(pipe.encode("utf-8"))

        lines = out.decode("utf-8", "ignore").split("\n")
        while True:
            retcode = p.poll()
            if retcode is not None:
                break
            else:
                lines.append(p.stdout.readline())
        return lines

    def get_key_from_pyasn(self, key, pyasn):
        ret = None
        if isinstance(pyasn, dict):
            for dkey, dval in pyasn.items():
                if dkey == key:
                    return dval
                else:
                    ret = self.get_key_from_pyasn(key, dval)
                    if ret:
                        break
        elif isinstance(pyasn, list):
            for item in pyasn:
                ret = self.get_key_from_pyasn(key, item)
                if ret:
                    break
        return ret

    def get_from_pyasn(self, key, msg):
        if not isinstance(msg, dict):
            msg = self.asn2py(msg)
        return self.get_key_from_pyasn(key, msg)

    def get_rrc_container(self, msg):
        return self.get_from_pyasn('RRCContainer', msg)

    def get_rrc_transaction_identifier(self, rrc_msg):
        return self.get_from_pyasn('rrc-TransactionIdentifier', rrc_msg)

    def get_rrc_from_container(self, msg):
        rrc_pdcp_hex = self.get_rrc_container(msg)
        return self.get_rrc_from_pdcp(rrc_pdcp_hex)

    def get_rrc_from_pdcp(self, rrc_pdcp_hex):
        rrc_hex = rrc_pdcp_hex[6:-8]
        return rrc_hex

    def get_nr_from_pdcp(self, rrc_pdcp_hex: str):
        if rrc_pdcp_hex.startswith('0x'):
            pdcp_nr = rrc_pdcp_hex[0:6]
        else:
            pdcp_nr = rrc_pdcp_hex[0:4]
        return int(pdcp_nr, 16)

    def extract_transaction_id(self, msg):
        # 'value TransactionID : 55'
        srch = re.search(r'value TransactionID : (\d+)', msg)
        if srch:
            return int(srch.group(1))
        return 0

    def extract_gnb_cu_ue_f1ap_id(self, msg):
        srch = re.search(r'value GNB-CU-UE-F1AP-ID : (\d+)', msg)
        if srch:
            return int(srch.group(1))
        return 0

    def extract_gnb_du_ue_f1ap_id(self, msg):
        srch = re.search(r'value GNB-DU-UE-F1AP-ID : (\d+)', msg)
        if srch:
            return int(srch.group(1))
        return 0

    def extract_srbid(self, msg):
        srch = re.search(r'value SRBID : (\d+)', msg)
        if srch:
            return int(srch.group(1))
        return 0

    def extract_ran_ue_ngap_id(self, msg):
        srch = re.search(r'value RAN-UE-NGAP-ID : (\d+)', msg)
        if srch:
            return int(srch.group(1))
        return 0

    def extract_time_to_wait(self, msg):
        # value TimeToWait : v1s
        srch = re.search(r'value TimeToWait : v(\d+)s', msg)
        if srch:
            return int(srch.group(1))
        return None
